def load() -> pd.DataFrame:
    import pandas as pd
    import glob

    pattern = 'data/astronomy/input/STORM-AI/warmup/v2/Sat_Density/swarma-wu???-201810??_to_201810??.csv'
    paths = sorted(glob.glob(pattern))
