def load() -> pd.DataFrame:
    import pandas as pd
    import glob
    import numpy as np

    pattern = 'data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201810??T235942_201810??T235942_0201/*.sp3'
    paths = sorted(glob.glob(pattern))
    if not paths:
        raise FileNotFoundError(f'No files matched pattern: {pattern}')

    rows = []
    current_epoch = None

    def parse_float(s):
        try:
            return float(s)
        except Exception:
            return np.nan

    for path in paths:
        with open(path, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if line.startswith('*'):
                    # Epoch line: *  yyyy mm dd hh mm ss.ssssssss
                    parts = line[1:].strip().split()
                    if len(parts) >= 6:
                        y, mo, d, hh, mm = map(int, parts[:5])
                        sec = float(parts[5])
                        # round to nearest microsecond
                        current_epoch = pd.Timestamp(y, mo, d, hh, mm, int(sec), tz='UTC') + pd.to_timedelta(sec - int(sec), unit='s')
                    else:
                        current_epoch = None
                elif line.startswith('P') and current_epoch is not None:
                    # Position line: P<sat> X Y Z CLK ... (km)
                    # We only need Swarm-A: satellite id is expected to start with 'PA' or 'PSA'? In Swarm POD it's usually 'P' + 3-char PRN.
                    sat_id = line[1:4].strip()
                    if sat_id not in ['SWA', 'A', 'SW1', '001', 'S1A', 'S1', 'SWA']:
                        # We'll still capture all sats; filter later by the most common sat id.
                        pass
                    x = parse_float(line[4:18].strip())
                    y = parse_float(line[18:32].strip())
                    z = parse_float(line[32:46].strip())
                    rows.append({
                        'epoch': current_epoch,
                        'sat_id': sat_id,
                        'x_km': x,
                        'y_km': y,
                        'z_km': z,
                        'source_file': path.split('/')[-1]
                    })

    df = pd.DataFrame(rows)
    # ensure datetime
    if not df.empty:
        df['epoch'] = pd.to_datetime(df['epoch'], utc=True)
    return df
